<?php
declare(strict_types=1);
session_start();
$root=dirname(__DIR__,3);
$cfg=require $root.'/config.php';
date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');
$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function go(string $u):never{header('Location: '.$u);exit;}
function csrf():void{if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(419);exit('Solicitud vencida.');}}
function replaceCharge(PDO $db,int $projectId,int $newChargeId,array $types):void{$m=implode(',',array_fill(0,count($types),'?'));$s=$db->prepare("SELECT id FROM charges WHERE project_id=? AND active=1 AND id<>? AND type IN ($m)");$s->execute(array_merge([$projectId,$newChargeId],$types));foreach($s as $old){$als=$db->prepare('SELECT payment_id,amount FROM allocations WHERE charge_id=?');$als->execute([$old['id']]);foreach($als as $al)$db->prepare('INSERT INTO allocations(payment_id,charge_id,amount) VALUES(?,?,?) ON DUPLICATE KEY UPDATE amount=amount+VALUES(amount)')->execute([$al['payment_id'],$newChargeId,$al['amount']]);$db->prepare('DELETE FROM allocations WHERE charge_id=?')->execute([$old['id']]);$db->prepare('UPDATE charges SET active=0 WHERE id=?')->execute([$old['id']]);}}
function uploadQuote(string $root):?string{if(empty($_FILES['quote_file']['name']))return null;if($_FILES['quote_file']['error']!==UPLOAD_ERR_OK||$_FILES['quote_file']['size']>8388608)throw new Exception('Archivo inválido o mayor a 8 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['quote_file']['tmp_name']);$ext=['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png'][$mime]??null;if(!$ext)throw new Exception('Solo se permiten PDF, JPG o PNG.');$name='presupuesto-'.bin2hex(random_bytes(8)).'.'.$ext;if(!move_uploaded_file($_FILES['quote_file']['tmp_name'],$root.'/storage/uploads/'.$name))throw new Exception('No se pudo guardar el archivo.');return 'storage/uploads/'.$name;}
if(empty($_SESSION['user']))go('index.php?a=dashboard');
$_SESSION['csrf']??=bin2hex(random_bytes(24));
$a=$_GET['a']??'new_quote';
if($a==='save_quote'){
 if(($_SESSION['user']['role']??'')!=='admin'){http_response_code(403);exit('No autorizado.');}
 csrf();
 try{
  $pid=(int)$_POST['project_id'];
  $families=array_values(array_intersect(['lifesmart','control4','shelly'],$_POST['quote_families']??[]));
  if(!$families)throw new Exception('Seleccioná al menos LifeSmart, Control4 o Shelly.');
  $items=[];$materials=0.0;
  foreach($_POST['items']??[] as $i=>$r){$d=trim((string)($r['description']??''));if($d==='')continue;$q=max(0,(float)($r['quantity']??0));$u=max(0,(float)($r['unit_price']??0));if($q<=0)continue;$st=round($q*$u,2);$materials+=$st;$items[]=[$r['category']??'Otros',$r['brand']??'Otro',$d,$q,$u,$st,(int)$i];}
  $labor=max(0,(float)($_POST['labor_amount']??0));$base=$materials+$labor;$mode=$_POST['tax_mode']??'sin_iva';$vat=(float)($_POST['vat_rate']??21);$factor=$mode==='mas_iva'?1+$vat/100:1;$materialsTotal=round($materials*$factor,2);$laborTotal=round($labor*$factor,2);$total=$materialsTotal+$laborTotal;$file=uploadQuote($root);
  $db->beginTransaction();
  $db->prepare('INSERT INTO quotes(project_id,version_no,quote_date,quote_families,materials_amount,labor_amount,subtotal,tax_mode,vat_rate,total,status,file_path,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$pid,(int)$_POST['version_no'],$_POST['quote_date'],implode(',',$families),$materials,$labor,$base,$mode,$vat,$total,$_POST['status'],$file,trim((string)($_POST['notes']??''))]);$qid=(int)$db->lastInsertId();
  $ins=$db->prepare('INSERT INTO quote_items(quote_id,category,brand,description,quantity,unit_price,subtotal,sort_order) VALUES(?,?,?,?,?,?,?,?)');foreach($items as $r)$ins->execute(array_merge([$qid],$r));
  if($_POST['status']==='aprobado_inicial'){$pct=(float)($_POST['engineering_pct']??10);$amt=round($total*$pct/100,2);$db->prepare("INSERT INTO charges(project_id,quote_id,charge_date,type,description,amount) VALUES(?,?,?,'ingenieria',?,?)")->execute([$pid,$qid,$_POST['quote_date'],'Adelanto de ingeniería '.$pct.'% · v'.$_POST['version_no'],$amt]);$eng=(int)$db->lastInsertId();replaceCharge($db,$pid,$eng,['ingenieria']);$db->prepare("UPDATE projects SET status='aprobado' WHERE id=?")->execute([$pid]);}
  if($_POST['status']==='final'){$db->prepare("INSERT INTO charges(project_id,quote_id,charge_date,type,description,amount) VALUES(?,?,?,'materiales',?,?)")->execute([$pid,$qid,$_POST['quote_date'],'Materiales · presupuesto final v'.$_POST['version_no'],$materialsTotal]);$mat=(int)$db->lastInsertId();replaceCharge($db,$pid,$mat,['materiales']);$db->prepare("INSERT INTO charges(project_id,quote_id,charge_date,type,description,amount) VALUES(?,?,?,'mano_obra',?,?)")->execute([$pid,$qid,$_POST['quote_date'],'Mano de obra · presupuesto final v'.$_POST['version_no'],$laborTotal]);$lab=(int)$db->lastInsertId();replaceCharge($db,$pid,$lab,['ingenieria','mano_obra']);$db->prepare("UPDATE projects SET status='en_obra' WHERE id=?")->execute([$pid]);}
  $db->commit();$_SESSION['msg']='Presupuesto multimarca cargado.';go('index.php?a=project&id='.$pid);
 }catch(Throwable $ex){if($db->inTransaction())$db->rollBack();$_SESSION['msg']='No se pudo guardar: '.$ex->getMessage();go('index.php?a=new_quote&project_id='.(int)($_POST['project_id']??0));}
}
$pid=(int)($_GET['project_id']??0);$s=$db->prepare('SELECT p.*,c.business_name,COALESCE(MAX(q.version_no),0)+1 nextv FROM projects p JOIN clients c ON c.id=p.client_id LEFT JOIN quotes q ON q.project_id=p.id WHERE p.id=? GROUP BY p.id');$s->execute([$pid]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Proyecto inexistente.');}$msg=$_SESSION['msg']??null;unset($_SESSION['msg']);
$cats=['Domótica','Redes','Cámaras','Alarma','Audio','Otros'];$brands=['LifeSmart','Control4','Shelly','Hikvision / Luma','Ubiquiti','Otro'];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nuevo presupuesto · Punto ERP</title><style>body{margin:0;background:#f4f6f8;color:#27303b;font:15px/1.45 system-ui}.wrap{max-width:1280px;margin:28px auto;padding:0 18px}.card{background:#fff;border:1px solid #e1e5e9;border-radius:14px;padding:22px}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}.c3{grid-column:span 3}.c4{grid-column:span 4}.c12{grid-column:span 12}label{display:block;font-weight:650;margin-bottom:6px}input,select,textarea{width:100%;padding:10px;border:1px solid #cbd1d7;border-radius:8px;box-sizing:border-box}.types{display:flex;gap:12px;flex-wrap:wrap}.types label{border:1px solid #e1e5e9;border-radius:10px;padding:12px 16px}.types input{width:auto}.btn{border:0;border-radius:8px;padding:10px 15px;background:#ff6702;color:#fff;font-weight:700;cursor:pointer;text-decoration:none;display:inline-block}.light{background:#edf0f3;color:#27303b}.muted{color:#6e7781}table{width:100%;border-collapse:collapse}th,td{padding:8px;border-bottom:1px solid #e1e5e9}th{text-align:left;font-size:12px;text-transform:uppercase;color:#6e7781}.flash{padding:12px;background:#fff0e5;border:1px solid #ffd2b1;border-radius:9px;margin-bottom:18px}@media(max-width:800px){.c3,.c4{grid-column:span 12}.scroll{overflow:auto}}</style></head><body><main class="wrap"><?php if($msg):?><div class="flash"><?=e($msg)?></div><?php endif;?><div class="card"><a href="index.php?a=project&id=<?=$pid?>">← Volver al proyecto</a><h1>Nuevo presupuesto</h1><p class="muted"><?=e($p['project_number'])?> · <?=e($p['name'])?> · <?=e($p['business_name'])?> · <?=e($p['currency'])?></p><form method="post" action="index.php?a=save_quote" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="project_id" value="<?=$pid?>"><input type="hidden" name="engineering_pct" value="<?=e($p['engineering_pct'])?>"><h3>Tipo de presupuesto</h3><p class="muted">Podés seleccionar uno o varios. Los productos pueden mezclarse libremente.</p><div class="types"><label><input type="checkbox" name="quote_families[]" value="lifesmart"> LifeSmart</label><label><input type="checkbox" name="quote_families[]" value="control4"> Control4</label><label><input type="checkbox" name="quote_families[]" value="shelly"> Shelly</label></div><div class="grid"><p class="c3"><label>Versión</label><input type="number" name="version_no" value="<?=e($p['nextv'])?>" required></p><p class="c3"><label>Fecha</label><input type="date" name="quote_date" value="<?=date('Y-m-d')?>" required></p><p class="c3"><label>Estado</label><select name="status"><option value="borrador">Borrador</option><option value="enviado">Enviado</option><option value="aprobado_inicial">Aprobado inicial</option><option value="final">Final</option><option value="rechazado">Rechazado</option></select></p><p class="c3"><label>Mano de obra</label><input type="number" step=".01" min="0" name="labor_amount" value="0" required></p><p class="c4"><label>IVA</label><select name="tax_mode"><option value="sin_iva">Sin IVA</option><option value="iva_incluido">IVA incluido</option><option value="mas_iva">Más IVA</option></select></p><p class="c4"><label>Alícuota %</label><input type="number" step=".01" name="vat_rate" value="<?=e($p['vat_rate'])?>"></p><p class="c4"><label>PDF / imagen</label><input type="file" name="quote_file" accept=".pdf,.jpg,.jpeg,.png"></p></div><h3>Productos / materiales</h3><p class="muted">Cada fila puede tener una marca y categoría distinta. El total de materiales se calcula con estas filas.</p><div class="scroll"><table><tr><th>Categoría</th><th>Marca</th><th>Descripción</th><th>Cantidad</th><th>Precio unit.</th></tr><?php for($i=0;$i<8;$i++):?><tr><td><select name="items[<?=$i?>][category]"><?php foreach($cats as $v):?><option><?=e($v)?></option><?php endforeach;?></select></td><td><select name="items[<?=$i?>][brand]"><?php foreach($brands as $v):?><option><?=e($v)?></option><?php endforeach;?></select></td><td><input name="items[<?=$i?>][description]"></td><td><input type="number" min="0" step=".01" name="items[<?=$i?>][quantity]" value="1"></td><td><input type="number" min="0" step=".01" name="items[<?=$i?>][unit_price]" value="0"></td></tr><?php endfor;?></table></div><p><label>Notas</label><textarea name="notes" rows="4"></textarea></p><button class="btn">Guardar presupuesto</button></form></div></main></body></html>
